"""Offline review view. No network, identity verification, approvals or publication."""
import json

def render(report):
 data=json.dumps(report,ensure_ascii=False,sort_keys=True,separators=(',',':'),allow_nan=False).replace('&','\\u0026').replace('<','\\u003c').replace('>','\\u003e').replace('\u2028','\\u2028').replace('\u2029','\\u2029')
 return TEMPLATE.replace('/*REPORT_DATA*/',data)

TEMPLATE=r'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="referrer" content="no-referrer"><title>Council of AI — engineering review</title><style>
:root{font:15px/1.55 system-ui,-apple-system,sans-serif;color:#172a34;background:#f3f6f8;--muted:#536872;--line:#d4dfe4;--accent:#155e57}*{box-sizing:border-box}main{max-width:1120px;margin:auto;padding:28px;overflow-wrap:anywhere;min-width:0}h1{font-size:32px;line-height:1.15;letter-spacing:-.8px;margin:8px 0 12px}h2{font-size:20px}h3{font-size:17px;margin:7px 0}p{margin:8px 0}.eyebrow{font-size:12px;text-transform:uppercase;letter-spacing:.14em;color:var(--accent);font-weight:750}.muted,small{font-size:13px;color:var(--muted)}.banner{border-left:4px solid var(--accent);padding:12px;background:#e4f1ed;border-radius:7px}.stats{display:grid;grid-template-columns:repeat(4,1fr);gap:10px;margin:22px 0}.stat,.card{background:white;border:1px solid var(--line);padding:16px;border-radius:12px}.stat strong{display:block;font-size:28px}.stat span{font-size:12px;color:var(--muted)}.toolbar{display:flex;gap:10px;flex-wrap:wrap;align-items:end;margin:18px 0}.toolbar label{flex:1;min-width:160px}label{display:block;font-weight:650;font-size:13px}input,select,textarea,button{font:inherit}input,select,textarea{width:100%;min-width:0;max-width:100%;border:1px solid var(--line);border-radius:7px;background:white;padding:9px;margin-top:5px;color:inherit}button{border:1px solid var(--accent);border-radius:8px;background:var(--accent);color:white;padding:9px 14px;cursor:pointer;min-height:42px}button.secondary{background:white;color:var(--accent)}:focus-visible{outline:3px solid #db9b39;outline-offset:3px}.grid{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:12px}.badge{font-size:11px;font-weight:700;padding:3px 7px;border-radius:5px;display:inline-block;background:#eef3f6;color:#385462}.warning{background:#fff0d9;color:#794a0c}.card{overflow-wrap:anywhere}.source{padding:12px 0;border-bottom:1px solid var(--line)}details{margin:12px 0}summary{cursor:pointer;font-weight:650}a{color:var(--accent)}code{font-size:12px;overflow-wrap:anywhere}.review{margin-top:25px;border:2px solid var(--accent)}footer{margin-top:25px;padding-top:16px;border-top:1px solid var(--line);color:var(--muted);font-size:12px}[hidden]{display:none!important}@media(max-width:680px){main{padding:16px}h1{font-size:27px}.stats{grid-template-columns:1fr 1fr}.grid{grid-template-columns:1fr}}
</style></head><body><main><header><div class="eyebrow">Council of AI · human review</div><h1>What changed. What is proved.<br>What still needs a decision.</h1><p id="date" class="muted"></p><div class="banner"><strong>Unsigned, review-only evidence.</strong> Source publication, controlled testing, deployment and outside acceptance are separate. This page cannot approve an action, send a finding, or change a system.</div></header>
<section class="stats" aria-label="Different evidence counts"><div class="stat"><strong id="n-work"></strong><span>tracked opportunities</span></div><div class="stat"><strong id="n-source"></strong><span>source locations observed</span></div><div class="stat"><strong id="n-change"></strong><span>changes against a retained pack</span></div><div class="stat"><strong id="n-closed"></strong><span>integrations closed by this report</span></div></section>
<section class="card" id="test-card"><div class="eyebrow">Scoped engineering result</div><h2>Evidence collection must finish before grading</h2><p id="test-result"></p><p id="test-scope" class="muted"></p><ul id="test-limits"></ul></section>
<section><h2>Review findings</h2><p id="comparison" class="muted"></p><div id="findings" class="grid"></div></section>
<section><h2>Existing opportunity queue</h2><div class="toolbar"><label>Area<select id="area"><option value="">All areas</option></select></label><label>Priority<select id="priority"><option value="">All priorities</option><option>P0</option><option>P1</option><option>P2</option></select></label><label>Find a task<input id="search" type="search" placeholder="For example: missing evidence"></label><button class="secondary" id="reset">Reset filters</button></div><p id="shown" role="status" class="muted"></p><div id="queue" class="grid"></div></section>
<details><summary>Source provenance and current read status</summary><div id="sources"></div></details>
<section class="card review"><h2>Prepare a human-review note</h2><p class="muted">This stays in your browser until you save it. A typed note is not an authenticated human decision or permission to execute. Nothing is sent.</p><label>Opportunity<select id="review-target"></select></label><label>What should the responsible owner check?<textarea id="note" rows="4" maxlength="4000" placeholder="Record the specific gap, evidence needed, or correction to review."></textarea></label><div class="toolbar"><button id="save-note">Save unsent review note</button><a href="report.json" download>Save report JSON</a><a href="report.md" download>Save readable report</a><a href="index.json" download>Save checksum index</a></div><p id="saved" role="status" class="muted"></p></section>
<footer><p id="value"></p><p>Exact-byte verification detects accidental changes against this index. It does not authenticate an issuer, prove a claim true, create IP ownership or establish financial value.</p><p>Report identity: <code id="identity"></code></p></footer></main>
<script id="report-data" type="application/json">/*REPORT_DATA*/</script><script>
'use strict';const r=JSON.parse(document.getElementById('report-data').textContent);const $=id=>document.getElementById(id);const node=(tag,text,cls='')=>{const n=document.createElement(tag);n.textContent=text??'';n.className=cls;return n;};
$('date').textContent='Reporting time: '+r.as_of+' · This is a retained observation, not an always-live feed.';$('identity').textContent=r.report_id;$('value').textContent=r.value_boundary;
for(const [id,key]of [['n-work','planned_opportunities'],['n-source','unique_source_locations'],['n-change','changed_records'],['n-closed','integrations_closed']])$(id).textContent=String(r.counts[key]);
$('comparison').textContent=r.comparison==='ACTUAL_PREVIOUS_PACK'?'Compared with retained report '+r.previous_report_id:'No prior pack was available. These are baseline observations, not new growth.';
function link(url){const a=node('a','Open official source');try{const u=new URL(url);if(u.protocol!=='https:'||u.username||u.password)throw Error();a.href=u.href;a.target='_blank';a.rel='noopener noreferrer';return a;}catch{return node('span','No valid source link');}}
for(const f of r.findings){const c=node('article','','card');c.append(node('span',f.kind.replaceAll('_',' '),'badge'),node('h3',f.status.replaceAll('_',' ')),node('p',f.action),link(f.url));$('findings').append(c);}if(!r.findings.length)$('findings').append(node('p','No substantive change in these collected records. Unobserved workflows are not declared complete.','muted'));
if(r.controlled_reproduction){const t=r.controlled_reproduction;$('test-result').textContent='Pinned collector/orchestrator cases: original '+t.baseline_passed+'/'+t.cases+'; candidate '+t.candidate_passed+'/'+t.cases+'. Deliberately disabled guard detected.';$('test-scope').textContent=t.scope;for(const x of t.limits)$('test-limits').append(node('li',x));}else{$('test-card').hidden=true;}
const areas=[...new Set(r.work.map(w=>w.area))].sort();for(const a of areas)$('area').append(node('option',a));for(const w of r.work){const o=node('option',w.id+' — '+w.opening);o.value=w.id;$('review-target').append(o);}
function render(){const area=$('area').value,p=$('priority').value,q=$('search').value.toLowerCase();const rows=r.work.filter(w=>(!area||w.area===area)&&(!p||w.priority===p)&&(!q||(w.id+' '+w.opening+' '+w.acceptance).toLowerCase().includes(q)));$('queue').replaceChildren();for(const w of rows){const c=node('article','','card');c.append(node('span',w.id+' · '+w.priority+' · '+w.area,'badge'),node('h3',w.opening),node('p',w.state.replaceAll('_',' '),'muted'));const d=document.createElement('details');d.append(node('summary','Acceptance and owner dependency'),node('p',w.acceptance),node('p',w.owner_gate,'muted'));c.append(d);const b=node('button','Review this task','secondary');b.addEventListener('click',()=>{$('review-target').value=w.id;$('note').focus();});c.append(b);$('queue').append(c);}$('shown').textContent=rows.length+' of '+r.work.length+' tasks shown. Status is evidence-scoped, not a percentage-complete claim.';}
for(const id of ['area','priority','search'])$(id).addEventListener('input',render);$('reset').addEventListener('click',()=>{$('area').value='';$('priority').value='';$('search').value='';render();});render();
for(const s of r.sources){const d=node('div','','source');d.append(node('strong',s.label+' — '+s.status.replaceAll('_',' ')),node('p','Retrieved: '+s.retrieved_at+' · Source updated: '+(s.source_updated_at??'not supplied'),'muted'),link(s.url),node('p','Source-byte hash: '+(s.raw_sha256??'unavailable'),'muted'));$('sources').append(d);}
$('save-note').addEventListener('click',()=>{const note=$('note').value.trim();if(!note){$('saved').textContent='Write the specific review action before saving.';return;}const d={schema:'csoai.local-review-note/1',state:'UNSENT_UNAUTHENTICATED_NOTE',report_id:r.report_id,opportunity_id:$('review-target').value,note,created_at:new Date().toISOString(),sent:false,grants_authority:false};const u=URL.createObjectURL(new Blob([JSON.stringify(d,null,2)+'\n'],{type:'application/json'}));const a=document.createElement('a');a.href=u;a.download='council-unsent-review-note.json';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(u),1000);$('saved').textContent='Saved locally. No organisation was notified and no action was authorised.';});
</script></body></html>'''
